// Define an interval type representing a closed interval [start, end].
#[derive(Debug, Clone, Copy, PartialEq)]
struct Interval {
    start: f32,
    end: f32,
}

// Laguerre series struct holding coefficients and intervals
#[derive(Debug, Clone, PartialEq)]
struct Laguerre {
    coefficients: Vec<f32>,
    domain: Interval,
    window: Interval,
}

fn make_laguerre(coefficients: Vec<f32>) -> Laguerre {
    // Define the unit interval [0.0, 1.0] for domain and window
    let unit_interval = Interval {
        start: 0.0,
        end: 1.0,
    };

    Laguerre {
        coefficients,
        domain: unit_interval,
        window: unit_interval,
    }
}